"""Verified generated bytes staged on the destination filesystem, POSIX only."""

import hashlib
import time
from contextlib import suppress

from core import files


def stage_bytes(root, path, data, processor, checkpoint=lambda: None):
    files._staging(path)
    if not root.writable or not 0 < len(data) <= processor.limits.max_output_bytes:
        raise files.FileError("LIMIT_EXCEEDED")
    inspected = processor.inspect(data)
    deadline = time.monotonic() + 120

    def guard():
        if time.monotonic() > deadline:
            raise files.FileError("COPY_TIMEOUT")
        checkpoint()

    return _write(root, path, data, inspected, guard)


def _write(root, path, data, inspected, checkpoint):
    created = None
    try:
        chunks = (memoryview(data)[offset : offset + files.CHUNK] for offset in range(0, len(data), files.CHUNK))
        info = root.write_stage(path, chunks, maximum=len(data), checkpoint=checkpoint)
        created = files.identity(info)
        copied, info = root.read(path, maximum=len(data), checkpoint=checkpoint)
        digest = hashlib.sha256(copied).hexdigest()
        if copied != data or digest != inspected.sha256:
            raise files.FileError("COPY_MISMATCH")
        return files.Stage(path, info, digest, len(data)), inspected
    except BaseException:
        if created is not None:
            with suppress(OSError, files.FileError):
                files.discard_stage(root, path, created)
        raise
